#!/usr/bin/env bash
set -euo pipefail

cd "$(git rev-parse --show-toplevel 2>/dev/null || pwd)"
SELF="$(basename "$0")"

echo "[1/4] A limpar o repositório..."
find . -mindepth 1 -maxdepth 1 ! -name .git ! -name "$SELF" -exec rm -rf {} +

echo "[2/4] A criar o projecto Hipertrofia Pro v7..."
mkdir -p .github/workflows
