chmod +x "$SELF" 2>/dev/null || true

echo "[3/4] A preparar commit..."
rm -f "$SELF"
git add -A
if git diff --cached --quiet; then
  echo "Nenhuma alteração para gravar."
else
  git commit -m "Install Hipertrofia Pro v7 Android project"
fi

echo "[4/4] A enviar para a branch main..."
git push origin HEAD:main

echo
echo "CONCLUÍDO: projecto v7 instalado e enviado para o GitHub."
echo "Agora abre a aba Actions no GitHub para acompanhar a compilação do APK."
